arguments.command:
# Get all dynamic function symbols sorted by address to find nearest match
# For addresses: 0x222098, 0x222234, 0x19bac0, 0x19bc14
objdump -T /tmp/libmonosgen-2.0.so 2>/dev/null | awk '/\.text/ && $4 != "" {print $1, $NF}' | sort > /tmp/dynsyms.txt
wc -l /tmp/dynsyms.txt

# Find surrounding symbols for each address
for addr in 222098 222234 19bac0 19bc14; do
  echo "=== 0x$addr ==="
  awk -v target="0x$addr" '
    BEGIN { target_dec = strtonum(target) }
    { 
      sym_dec = strtonum("0x" $1)
      if (sym_dec <= target_dec) { prev_addr = $1; prev_name = $2 }
      if (sym_dec > target_dec && !found) { found=1; printf "  -> %s+0x%x (next: %s @ 0x%s)\n", prev_name, target_dec - strtonum("0x" prev_addr), $2, $1 }
    }
  ' /tmp/dynsyms.txt
done

