arguments.command:
# The binary is stripped but has dynamic symbols. Let's use a finer-grained approach.
# nm -D gives all dynamic symbols including sizes
nm -D --defined-only -S /tmp/libmonosgen-2.0.so | sort -k1 | awk '
BEGIN {
  addrs[1] = strtonum("0x222098")
  addrs[2] = strtonum("0x222234")
  addrs[3] = strtonum("0x19bac0")
  addrs[4] = strtonum("0x19bc14")
}
{
  sym_addr = strtonum("0x" $1)
  sym_size = strtonum("0x" $2)
  sym_name = $4
  for (i = 1; i <= 4; i++) {
    if (addrs[i] >= sym_addr && addrs[i] < sym_addr + sym_size) {
      printf "0x%x -> %s+0x%x\n", addrs[i], sym_name, addrs[i] - sym_addr
    }
  }
}' 2>/dev/null

